import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import './ProductOverview.css';

const ProductOverview = () => {
  const { productId } = useParams();

  // --- UI STATES ---
  const [activeCategory, setActiveCategory] = useState('Air Quality');
  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
  const [isSolutionsMenuOpen, setIsSolutionsMenuOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [mobileProductExpanded, setMobileProductExpanded] = useState(false);
  const [mobileSolutionsExpanded, setMobileSolutionsExpanded] = useState(false);

  // --- STATIC SOLUTIONS LIST ---
  const solutionsList = [
    { name: 'Air Quality Monitoring', link: '/project/intelligent-sensor' },
    { name: 'Flood Alert System', link: '/project/water-level' },
    { name: 'Digital Water Distribution', link: '/project/digital-water' },
    { name: 'Startup & Skill Development', link: '/project/startup-skill' }
  ];

  // --- UPDATED MENU STRUCTURE ---
  const productMenuData = {
    'Air Quality': {
      title: 'Air Quality Monitoring',
      description: 'Precision sensors for indoor and outdoor environments.',
      items: [
        { name: 'AQMS-Indoor', image: '/sensor_modules/aqms-station1.jpg', link: '/product-details/indoor-monitor' },
        { name: 'AQMS-Outdoor', image: '/sensor_modules/aqi1.jpeg', link: '/project/intelligent-sensor' },
        { name: 'Gas Sensors', image: '/sensor_modules/aqi-indoor.jpeg', link: '/product-details/gas-sensors' }
      ]
    },
    'Water Solutions': {
      title: 'Water Management',
      description: 'Flood alerts and distribution logic.',
      items: [
        { name: 'Predictive Flood Alert', image: '/sensor_modules/river1.jpg', link: '/project/water-level' },
        { name: 'Digital Flow Meter', image: '/sensor_modules/distribution.jpeg', link: '/project/digital-water' }
      ]
    },
    'Weather': {
      title: 'Weather Stations',
      description: 'Hyper-local weather data collection.',
      items: [
        { name: 'AWS', image: '/sensor_modules/weather.jpg', link: '/product-details/weather-station' },
      ]
    },
    'Training': {
      title: 'Skill Development',
      description: 'Kits and workshops for students.',
      items: [
        { name: 'IoT Workshops & Internships', image: '/sensor_modules/skill.jpg', link: '/project/startup-skill' },
        { name: 'PCB Design Course', image: 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=400', link: '/product-details/pcb-workshop' }
      ]
    }
  };

  // --- UPDATED PROJECTS DATA (From User Input) ---
  const projectsData = {
    'intelligent-sensor': {
      title: 'AQMS- Advanced Air Quality Monitoring',
      tagline: 'Real-time. Reliable. Rugged.',
      heroImage: 'https://images.unsplash.com/photo-1529619768328-e37af76c6fe5?q=80&w=2000&auto=format&fit=crop',
      subimage: '/sensor_modules/aqi1.jpeg',
      description: 'A comprehensive environmental monitoring solution measuring NO2, SO2, NH3, O3, PM2.5, and PM10 with LoRaWAN connectivity.',
      fullDescription: `The AQMS is a state-of-the-art monitoring station designed for both urban and industrial applications. It integrates high-precision laser dispersion sensors and NTC thermistors to track pollutants and weather data in real-time. Built with a rugged IP67 enclosure, it ensures continuous operation with dual connectivity (LoRa + GSM) and backup power.`,
      innovations: [
        { title: 'Multi-Gas Sensing', desc: 'Measures NO2, SO2, NH3, O3, PM2.5, PM10.', icon: '🔬' },
        { title: 'Dual Connectivity', desc: 'LoRaWAN for long range + GSM backup.', icon: '📡' },
        { title: 'Design', desc: 'IP67 Weatherproof & Durable enclosure.', icon: '🛡️' },
        { title: 'Data Security', desc: 'SD Card backup & AWS Cloud integration.', icon: '☁️' }
      ],
      applications: [
        { 
          title: 'Town Junctions', 
          image: 'https://images.unsplash.com/photo-1622036611950-840fb662c47e?w=800', 
          desc: 'Monitoring traffic emissions at busy local bus stands.' 
        },
        { 
          title: 'Taluk Hospitals', 
          image: 'https://images.unsplash.com/photo-1584555613497-9ecf9dd06f68?w=800', 
          desc: 'Ensuring sterile air quality near patient wards.' 
        },
        { 
          title: 'Local Markets', 
          image: 'https://images.unsplash.com/photo-1463592176946-907153ba4343?w=800', 
          desc: 'Tracking dust and waste burning levels in busy markets.' 
        }
      ],
      impacts: [
        { label: 'Pollutants', value: '6 Types' }, { label: 'Rating', value: 'IP67' },
        { label: 'Comms', value: 'LoRa/GSM' }, { label: 'Backup', value: '24hr UPS' }
      ]
    },
    'water-level': {
      title: 'Predictive Flood Alert System',
      tagline: 'Predicting Water Levels 6 Hours Ahead.',
      heroImage: 'https://images.unsplash.com/photo-1454789476662-53eb23ba5907?q=80&w=2000&auto=format&fit=crop',
      subimage: '/sensor_modules/river1.jpg',
      description: 'Using advanced LSTM Deep Learning networks to provide accurate river level forecasting and flood warnings.',
      fullDescription: `This system addresses the challenge of sudden floods by predicting river levels up to 6 hours in advance. It integrates multi-source data including upstream dam operations, real-time rainfall patterns, and historical river measurements into a comprehensive LSTM Neural Network model.`,
      innovations: [
        { title: 'LSTM Network', desc: 'Deep learning for 6-hour advance prediction.', icon: '🧠' },
        { title: 'Multi-Source Data', desc: 'Integrates Dam + Rainfall + River levels.', icon: '🌊' },
        { title: 'Real-Time Alert', desc: 'Instant notifications for emergency response.', icon: '🚨' },
        { title: 'Ultrasonic Accuracy', desc: 'Precision level monitoring sensors.', icon: '📏' }
      ],
      applications: [
        { 
          title: 'Riverside Homes', 
          image: 'https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?w=800', 
          desc: 'Alerting low-lying households in Neeleswaram.' 
        },
        { 
          title: 'Local Causeways', 
          image: 'https://images.unsplash.com/photo-1588790740929-ca95fb7e2cb1?w=800', 
          desc: 'Warning traffic before small bridges get submerged.' 
        },
        { 
          title: 'Paddy Fields', 
          image: 'https://images.unsplash.com/photo-1597906936547-823422196536?w=800', 
          desc: 'Protecting seasonal agriculture near river banks.' 
        }
      ],
      impacts: [
        { label: 'Lead Time', value: '6 Hours' }, { label: 'Model', value: 'LSTM' },
        { label: 'Accuracy', value: '98%' }, { label: 'Region', value: 'Kerala' }
      ]
    },
    'digital-water': {
      title: 'Digital Water Distribution',
      tagline: 'Smart flow for smart cities.',
      heroImage: 'https://images.unsplash.com/photo-1516937941348-c09645f3a2eb?q=80&w=2000&auto=format&fit=crop',
      subimage: '/sensor_modules/distribution.jpeg',
      description: 'A digital twin system built to monitor, analyze, and optimize local water distribution networks.',
      fullDescription: `We conducted comprehensive ground studies engaging with KWA officials. This system digitizes the water network to ensure fair distribution, detect leaks instantly, and manage pressure across the pipeline network using IoT flow meters.`,
      innovations: [
        { title: 'Digital Twin', desc: 'Virtual replica of pipe networks.', icon: '💻' },
        { title: 'Leak Detection', desc: 'Instant pressure drop alerts.', icon: '💧' },
        { title: 'Flow Analysis', desc: 'Real-time consumption tracking.', icon: '📊' },
        { title: 'Remote Valve', desc: 'Control water flow from the cloud.', icon: '🎛️' }
      ],
      applications: [
        { 
          title: 'Panchayat Wards', 
          image: 'https://images.unsplash.com/photo-1625641323035-63d924c05533?w=800', 
          desc: 'Equitable water distribution for village wards.' 
        },
        { 
          title: 'Pump Houses', 
          image: 'https://images.unsplash.com/photo-1565354689339-503630dae468?w=800', 
          desc: 'Automating local KWA sub-station operations.' 
        },
        { 
          title: 'Housing Colonies', 
          image: 'https://images.unsplash.com/photo-1560179707-f14e90ef3623?w=800', 
          desc: 'Leak detection for local residential associations.' 
        }
      ],
      impacts: [
        { label: 'Partner', value: 'KWA' }, { label: 'Goal', value: 'Efficiency' },
        { label: 'Tech', value: 'XAI' }, { label: 'Method', value: 'Digital Twin' }
      ]
    },
    'startup-skill': {
      title: 'IoT & Embedded Systems Training',
      tagline: 'Hands-on Workshops & Internships.',
      heroImage: 'https://images.unsplash.com/photo-1581092918056-0c4c3acd3789?q=80&w=2000&auto=format&fit=crop',
      subimage: '/sensor_modules/skill.jpg',
      description: 'Comprehensive training programs ranging from 1-day workshops to intensive 15-day internships on IoT and Edge Computing.',
      fullDescription: `We bridge the gap between academia and industry by providing hands-on training in Arduino, Raspberry Pi, PCB Design (KiCad), and IoT prototyping. Our programs culminate in real-world project expos and prototype development.`,
      innovations: [
        { title: 'Summer Internship', desc: '15 Days on Electronic Prototyping.', icon: '📅' },
        { title: 'PCB Design', desc: 'KiCad & Edge Hardware Workshop.', icon: '🛠️' },
        { title: 'IoT Robotics', desc: 'ESP8266 to Raspberry Pi integration.', icon: '🤖' },
        { title: 'Computer Vision', desc: 'Raspberry Pi & OpenCV training.', icon: '👁️' }
      ],
      applications: [
        { 
          title: 'Local Colleges', 
          image: 'https://images.unsplash.com/photo-1564981797816-1043664bf78d?w=800', 
          desc: 'Workshops for nearby Engineering & Polytechnic institutes.' 
        },
        { 
          title: 'District Schools', 
          image: 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800', 
          desc: 'Setting up ATAL Tinkering Labs in local schools.' 
        },
        { 
          title: 'Community Centers', 
          image: 'https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800', 
          desc: 'Weekend robotics camps for neighborhood students.' 
        }
      ],
      impacts: [
        { label: 'Interns', value: '19+' },
        { label: 'Workshops', value: '8+' },
        { label: 'Startups', value: '6 Teams' },
        { label: 'Staff', value: '6' }
      ]
    },
    'default': {
      title: "Product Not Found",
      tagline: "Please select a product from the menu.",
      heroImage: "https://images.unsplash.com/photo-1518770660439-4636190af475?w=800",
      description: "The product you are looking for is currently unavailable.",
      innovations: [],
      impacts: []
    }
  };

  const product = projectsData[productId] || projectsData['default'];

  useEffect(() => {
    if (isMobileMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'auto';
    }
    window.scrollTo(0, 0);
  }, [isMobileMenuOpen, productId]);

  return (
    <div className="project-page">
      {/* 1. HEADER (Fully Responsive) */}
      <header className="aiiot-header-local">
         <div className="project-header-inner">
             {/* Logo */}
             <Link to="/" className="logo-link">
               <div className="logo-box">
                 <img src="/logo/logo.png" alt="Adi Shankara Institute" style={{ height: '100%', width: 'auto' }} />
               </div>
               <div style={{ display: 'flex', flexDirection: 'column' }}>
                 <span style={{ fontSize: '1.1rem', fontWeight: 700, color: '#1e293b', lineHeight: 1.2 }}>AI-IoT Innovations</span>
               </div>
             </Link>
 
             {/* DESKTOP NAV */}
             <div className="project-desktop-nav">
               <Link to="/" className="project-nav-link">Home</Link>
               
               {/* Solutions Dropdown */}
               <div 
                   className="dropdown-wrapper"
                   onMouseEnter={() => setIsSolutionsMenuOpen(true)}
                   onMouseLeave={() => setIsSolutionsMenuOpen(false)}
               >
                   <div className="project-nav-link product-trigger" style={{ cursor: 'pointer' }}>
                     Solutions <span>▾</span>
                   </div>
                   <div className={`simple-dropdown ${isSolutionsMenuOpen ? 'visible' : ''}`}>
                     {solutionsList.map((sol, index) => (
                       <Link key={index} to={sol.link} className="simple-dropdown-item">
                         {sol.name}
                       </Link>
                     ))}
                   </div>
               </div>

               {/* Products Mega Menu */}
               <div 
                 className="mega-menu-wrapper"
                 onMouseEnter={() => setIsMegaMenuOpen(true)}
                 onMouseLeave={() => setIsMegaMenuOpen(false)}
               >
                 <Link to="" className="project-nav-link product-trigger">
                   Products <span>▾</span>
                 </Link>
                 <div className={`mega-menu-container ${isMegaMenuOpen ? 'visible' : ''}`}>
                   <div className="mega-menu-sidebar">
                     {Object.keys(productMenuData).map((key) => (
                       <div 
                         key={key} 
                         className={`mega-sidebar-item ${activeCategory === key ? 'active' : ''}`}
                         onMouseEnter={() => setActiveCategory(key)}
                       >
                         {key} <span>›</span>
                       </div>
                     ))}
                   </div>
                   <div className="mega-menu-content">
                     <div className="mega-content-header">
                       <h4>{productMenuData[activeCategory].title}</h4>
                       <p>{productMenuData[activeCategory].description}</p>
                     </div>
                     <div className="mega-grid">
                       {productMenuData[activeCategory].items.map((item, idx) => (
                         <Link to={item.link} key={idx} className="mega-product-card">
                            <div className="mega-img-box">
                              <img src={item.image} alt={item.name} />
                            </div>
                            <span>{item.name}</span>
                         </Link>
                       ))}
                     </div>
                   </div>
                 </div>
               </div>
               
               <Link to="/resources" className="project-nav-link">R&D Mission</Link>
               <a href="#contact" className="btn-primary-small">Get in Touch</a>
             </div>
 
             {/* MOBILE HAMBURGER */}
             <button className="mobile-nav-toggle" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
               {isMobileMenuOpen ? '✕' : '☰'}
             </button>
         </div>

         {/* MOBILE MENU OVERLAY */}
         {isMobileMenuOpen && (
            <div className="mobile-menu-wrapper">
                <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className="mobile-link">Home</Link>
                
                {/* Solutions Accordion */}
                <div style={{ borderBottom: '1px solid #f1f5f9', paddingBottom: '0.5rem' }}>
                    <div 
                        onClick={() => setMobileSolutionsExpanded(!mobileSolutionsExpanded)}
                        style={{ display: 'flex', justifyContent: 'space-between', alignItems:'center', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', cursor: 'pointer' }}
                    >
                        Solutions <span>{mobileSolutionsExpanded ? '▴' : '▾'}</span>
                    </div>
                    {mobileSolutionsExpanded && (
                        <div style={{ background: '#f8fafc', padding: '0.5rem 1rem', borderRadius: '8px' }}>
                            {solutionsList.map((sol, i) => (
                                <Link 
                                    key={i} 
                                    to={sol.link} 
                                    onClick={() => setIsMobileMenuOpen(false)}
                                    style={{ display: 'block', padding: '0.5rem 0', fontSize: '0.95rem', color: '#475569', textDecoration: 'none', borderBottom: i !== solutionsList.length -1 ? '1px solid #e2e8f0' : 'none' }}
                                >
                                    • {sol.name}
                                </Link>
                            ))}
                        </div>
                    )}
                </div>

                {/* Products Accordion */}
                <div style={{ borderBottom: '1px solid #f1f5f9', paddingBottom: '0.5rem' }}>
                    <div 
                        onClick={() => setMobileProductExpanded(!mobileProductExpanded)}
                        style={{ display: 'flex', justifyContent: 'space-between', alignItems:'center', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', cursor: 'pointer' }}
                    >
                        Products <span>{mobileProductExpanded ? '▴' : '▾'}</span>
                    </div>
                    {mobileProductExpanded && (
                        <div style={{ background: '#f8fafc', padding: '1rem', borderRadius: '8px' }}>
                            {Object.keys(productMenuData).map((categoryKey) => (
                                <div key={categoryKey} style={{ marginBottom: '1rem' }}>
                                    <div style={{ fontSize: '0.85rem', color: '#3b82f6', fontWeight: '700', textTransform: 'uppercase', marginBottom:'0.5rem' }}>{categoryKey}</div>
                                    {productMenuData[categoryKey].items.map((item, i) => (
                                        <Link 
                                            key={i} 
                                            to={item.link} 
                                            onClick={() => setIsMobileMenuOpen(false)}
                                            style={{ display: 'block', padding: '0.25rem 0', fontSize: '0.95rem', color: '#475569', textDecoration: 'none' }}
                                        >
                                            • {item.name}
                                        </Link>
                                    ))}
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <Link to="/resources" onClick={() => setIsMobileMenuOpen(false)} className="mobile-link">Resources</Link>
                <a href="#contact" onClick={() => setIsMobileMenuOpen(false)} className="btn-primary" style={{ textAlign: 'center', marginTop: '1rem', display:'block' }}>Get in Touch</a>
            </div>
         )}
      </header>

      {/* 2. MAIN CONTENT */}
      <div className="container" style={{paddingTop: '8rem', paddingBottom: '5rem'}}>
        
        {/* HERO SECTION */}
        <div className="product-hero-section">
          <div className="product-text-side">
            <span className="product-badge">Project Showcase</span>
            <h1 className="product-title">{product.title}</h1>
            <p className="product-tagline">{product.tagline}</p>
            <p className="product-desc">{product.description}</p>
            
            <div style={{marginTop:'2rem'}}>
               <button className="btn-primary">Learn More</button>
            </div>
          </div>

          <div className="product-image-side">
             <img src={product.heroImage} alt={product.title} />
          </div>
        </div>

        {/* FULL DESCRIPTION */}
        {product.fullDescription && (
            <div style={{ maxWidth: '800px', margin: '4rem auto', textAlign: 'center', lineHeight: '1.8', color: '#475569', fontSize: '1.1rem' }}>
                <p>{product.fullDescription}</p>
            </div>
        )}

        {/* INNOVATIONS GRID (Replaces Features) */}
        {product.innovations && (
            <div className="innovations-section">
                <h3 style={{ textAlign: 'center', marginBottom: '3rem', fontSize: '2rem', color: '#1e293b' }}>Key Innovations</h3>
                <div className="innovations-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '2rem' }}>
                    {product.innovations.map((item, i) => (
                        <div key={i} className="innovation-card" style={{ padding: '2rem', background: 'white', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
                            <div style={{ fontSize: '2.5rem', marginBottom: '1rem' }}>{item.icon}</div>
                            <h4 style={{ fontSize: '1.2rem', fontWeight: '700', marginBottom: '0.5rem', color: '#1e293b' }}>{item.title}</h4>
                            <p style={{ color: '#64748b', fontSize: '0.95rem' }}>{item.desc}</p>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* APPLICATIONS SECTION (Replaces "Where We Deploy") */}
        {product.applications && (
            <div className="applications-section" style={{ marginTop: '5rem' }}>
                <h3 style={{ fontSize: '2rem', color: '#1e293b', marginBottom: '2rem' }}>Deployment Areas</h3>
                <div className="applications-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '2rem' }}>
                    {product.applications.map((app, i) => (
                        <div key={i} className="app-card" style={{ borderRadius: '16px', overflow: 'hidden', border: '1px solid #e2e8f0', background: 'white' }}>
                            <div style={{ height: '200px', overflow: 'hidden' }}>
                                <img src={app.image} alt={app.title} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                            </div>
                            <div style={{ padding: '1.5rem' }}>
                                <h4 style={{ fontSize: '1.2rem', fontWeight: '700', marginBottom: '0.5rem' }}>{app.title}</h4>
                                <p style={{ color: '#64748b', fontSize: '0.95rem' }}>{app.desc}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* IMPACTS METRICS (Replaces Specs) */}
        {product.impacts && (
           <div className="impacts-container" style={{ marginTop: '5rem', background: '#f8fafc', padding: '3rem', borderRadius: '16px' }}>
              <h3 style={{ textAlign: 'center', marginBottom: '2rem', fontSize: '1.5rem' }}>Project Impact</h3>
              <div className="impacts-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '2rem', textAlign: 'center' }}>
                {product.impacts.map((imp, idx) => (
                   <div key={idx} className="impact-item">
                      <div style={{ fontSize: '0.9rem', textTransform: 'uppercase', letterSpacing: '1px', color: '#64748b', marginBottom: '0.5rem' }}>{imp.label}</div>
                      <div style={{ fontSize: '1.8rem', fontWeight: '800', color: '#2563eb' }}>{imp.value}</div>
                   </div>
                ))}
              </div>
           </div>
        )}

      </div>
    </div>
  );
};

export default ProductOverview;
